from rules import amount


def solve(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}

    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue

        if "id" in event:
            identity = ("id", event["id"])
        else:
            identity = ("anonymous", position)

        revision = event.get("revision", 0)
        previous = winners.get(identity)
        if previous is None or revision >= previous[0]:
            winners[identity] = (revision, position, event)

    balances = dict(data.get("opening", {}))
    for _, _, event in sorted(winners.values(), key=lambda winner: winner[1]):
        if event.get("void", False):
            continue

        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = f"{account}|{currency}"
        balances[key] = balances.get(key, 0) + amount(event, data["rounding"])

    return {"balances": balances}

def _round_ratio(numerator, mode):
    if mode == "floor":
        return numerator // 10000
    if mode == "half_up":
        return (numerator + 5000) // 10000
    raise ValueError("unsupported rounding mode")


def amount(event, mode):
    gross = event["price"] * event.get("quantity", 1)
    discount_bp = max(0, min(10000, event.get("discount_bp", 0)))
    net = _round_ratio(gross * (10000 - discount_bp), mode)

    tax_bp = event.get("tax_bp", 0)
    tax = _round_ratio(net * tax_bp, mode)
    total = net + tax

    if event.get("kind") == "refund":
        total = -total
    return total
